@FunctionalInterface
interface StringProcessor {
    String process(String input); // JEDYNA metoda liczaca sie do SAM

    @Override
    boolean equals(Object obj); // NIE liczy sie - z Object

    default String processTwice(String input) {
        return process(process(input)); // NIE liczy sie - default
    }

    default StringProcessor andThen(StringProcessor after) {
        return input -> after.process(this.process(input));
    }

    static StringProcessor identity() {
        return input -> input; // NIE liczy sie - static
    }
}

@FunctionalInterface
interface TriFunction<A, B, C, R> {
    R apply(A a, B b, C c);
}

@FunctionalInterface
interface CheckedFunction<T, R> {
    R apply(T t) throws Exception; // wlasna sygnatura z throws
}
